// Extract and normalize incident data from webhook payload
const items = $input.all();
const normalizedItems = [];

for (const item of items) {
  const payload = item.json.body || item.json;

  const normalized = {
    incidentId: payload.incidentId || payload.incident_id || null,
    source: payload.source || null,
    sourceType: payload.sourceType || payload.source_type || null,
    title: payload.title || null,
    severity: payload.severity || null,
    logs: payload.logs || null,
    branch: payload.branch || null,
    repository: payload.repository || payload.repo || null
  };

  normalizedItems.push({ json: normalized });
}

return normalizedItems;

// Extract Jenkins-specific context from incident data
const items = $input.all();
const enrichedItems = [];

for (const item of items) {
  const incident = item.json;

  // Parse Jenkins-specific fields from logs or source data
  const jenkinsContext = {
    buildNumber: incident.logs?.buildNumber || incident.buildNumber || null,
    jobName: incident.logs?.jobName || incident.jobName || null,
    pipelineStage: incident.logs?.stage || incident.stage || null,
    buildUrl: incident.logs?.buildUrl || incident.buildUrl || null,
    buildStatus: incident.logs?.status || incident.status || null,
    duration: incident.logs?.duration || incident.duration || null,
    triggeredBy: incident.logs?.triggeredBy || incident.triggeredBy || null,
    node: incident.logs?.node || incident.node || null
  };

  // Merge original incident data with Jenkins context
  const enriched = {
    ...incident,
    jenkinsContext,
    enrichedAt: new Date().toISOString(),
    enrichmentSource: 'jenkins'
  };

  enrichedItems.push({ json: enriched });
}

return enrichedItems;

// Extract and enrich SonarQube-specific context from incident data
const items = $input.all();
const enrichedItems = [];

for (const item of items) {
  const incident = item.json;

  // Parse logs if they're in string format
  let logs = incident.logs;
  if (typeof logs === 'string') {
    try {
      logs = JSON.parse(logs);
    } catch (e) {
      logs = { raw: logs };
    }
  }

  // Extract SonarQube-specific context
  const sonarQubeContext = {
    projectKey: logs?.projectKey || logs?.project?.key || null,
    projectName: logs?.projectName || logs?.project?.name || null,
    qualityGateStatus: logs?.qualityGate?.status || logs?.status || null,
    qualityGateConditions: logs?.qualityGate?.conditions || [],
    metrics: {
      bugs: logs?.bugs || logs?.metrics?.bugs || 0,
      vulnerabilities: logs?.vulnerabilities || logs?.metrics?.vulnerabilities || 0,
      codeSmells: logs?.codeSmells || logs?.code_smells || logs?.metrics?.code_smells || 0,
      securityHotspots: logs?.securityHotspots || logs?.security_hotspots || logs?.metrics?.security_hotspots || 0,
      coverage: logs?.coverage || logs?.metrics?.coverage || null,
      duplications: logs?.duplications || logs?.metrics?.duplications || null,
      technicalDebt: logs?.technicalDebt || logs?.technical_debt || logs?.metrics?.sqale_index || null
    },
    branch: incident.branch || logs?.branch?.name || 'main',
    analysisDate: logs?.analysedAt || logs?.analysis_date || new Date().toISOString(),
    serverUrl: logs?.serverUrl || logs?.server_url || null,
    dashboardUrl: logs?.dashboardUrl || logs?.dashboard_url || null
  };

  // Create enriched incident structure
  const enriched = {
    ...incident,
    enrichedContext: {
      source: 'sonarqube',
      timestamp: new Date().toISOString(),
      sonarqube: sonarQubeContext
    },
    // Add summary for quick reference
    summary: {
      totalIssues: sonarQubeContext.metrics.bugs + sonarQubeContext.metrics.vulnerabilities + sonarQubeContext.metrics.codeSmells,
      criticalIssues: sonarQubeContext.metrics.bugs + sonarQubeContext.metrics.vulnerabilities,
      qualityGatePassed: sonarQubeContext.qualityGateStatus === 'OK' || sonarQubeContext.qualityGateStatus === 'PASSED',
      projectKey: sonarQubeContext.projectKey
    }
  };

  enrichedItems.push({ json: enriched });
}

return enrichedItems;

// Extract and enrich GitHub-specific context from incident data
const items = $input.all();
const enrichedItems = [];

for (const item of items) {
  const incident = item.json;

  // Extract GitHub-specific fields
  const githubContext = {
    prNumber: incident.prNumber || incident.pr_number || incident.pullRequestNumber || null,
    commitSha: incident.commitSha || incident.commit_sha || incident.sha || null,
    workflowRun: incident.workflowRun || incident.workflow_run || incident.runId || null,
    actionType: incident.actionType || incident.action_type || incident.action || null,
    actor: incident.actor || incident.user || null,
    ref: incident.ref || incident.branch || null,
    workflowName: incident.workflowName || incident.workflow_name || null,
    jobName: incident.jobName || incident.job_name || null,
    conclusion: incident.conclusion || incident.status || null,
    htmlUrl: incident.htmlUrl || incident.html_url || incident.url || null
  };

  // Build enriched incident structure
  const enriched = {
    ...incident,
    enrichedContext: {
      source: 'github',
      github: githubContext,
      enrichedAt: new Date().toISOString()
    }
  };

  enrichedItems.push({ json: enriched });
}

return enrichedItems;

// Extract generic context from incident data
const items = $input.all();
const enrichedItems = [];

for (const item of items) {
  const incident = item.json;

  // Extract generic context information
  const enrichedIncident = {
    ...incident,
    enrichedContext: {
      timestamp: new Date().toISOString(),
      environment: incident.environment || 'unknown',
      tags: incident.tags || [],
      metadata: incident.metadata || {},
      customFields: incident.customFields || {},
      processedAt: new Date().toISOString(),
      enrichmentSource: 'generic'
    }
  };

  enrichedItems.push({ json: enrichedIncident });
}

return enrichedItems;

// Build a complete JSON package with incident data, enriched context, and analysis directives for AI agents
const items = $input.all();
const analysisPackages = [];

for (const item of items) {
  const incident = item.json;

  // Extract enriched context based on source type
  const enrichedContext = incident.enrichedContext || {};
  const sourceType = incident.sourceType || 'generic';

  // Build analysis directives based on source type and severity
  const analysisDirectives = {
    rootCauseAnalysis: {
      enabled: true,
      focus: [
        'Identify the primary failure point',
        'Analyze contributing factors',
        'Determine if this is a recurring issue',
        'Assess impact on downstream systems'
      ],
      context: sourceType
    },
    securityRiskAnalysis: {
      enabled: true,
      focus: [
        'Evaluate security implications',
        'Identify potential vulnerabilities exposed',
        'Assess data exposure risk',
        'Determine compliance impact'
      ],
      severity: incident.severity || 'medium'
    },
    remediationFeasibility: {
      enabled: true,
      focus: [
        'Suggest immediate mitigation steps',
        'Propose long-term fixes',
        'Estimate implementation effort',
        'Identify required resources and expertise'
      ],
      priority: incident.severity === 'critical' || incident.severity === 'high' ? 'urgent' : 'normal'
    }
  };

  // Build the complete analysis package
  const analysisPackage = {
    incidentId: incident.incidentId,
    timestamp: new Date().toISOString(),
    source: {
      type: sourceType,
      name: incident.source,
      repository: incident.repository,
      branch: incident.branch
    },
    incident: {
      title: incident.title,
      severity: incident.severity,
      logs: incident.logs,
      rawData: {
        incidentId: incident.incidentId,
        sourceType: incident.sourceType,
        source: incident.source
      }
    },
    enrichedContext: enrichedContext,
    analysisDirectives: analysisDirectives,
    metadata: {
      packageVersion: '1.0',
      createdAt: new Date().toISOString(),
      workflowId: $workflow.id,
      executionId: $execution.id
    }
  };

  analysisPackages.push({ json: analysisPackage });
}

return analysisPackages;
